<?php
declare(strict_types=1);
ini_set('display_errors','0');require dirname(__DIR__).'/private/app.php';require dirname(__DIR__).'/private/lifecycle/routes.php';require dirname(__DIR__).'/private/support/core.php';security_headers();header('Cache-Control: private, no-store');header('Content-Type: application/json; charset=utf-8');
try{$customer=($_GET['mode']??'customer')!=='owner';$method=$_SERVER['REQUEST_METHOD'];$a=cc_actor($customer,$method!=='GET');$r=$_GET['r']??'orders';rate('support-api',120);
 if($method==='GET'){
  if($r==='orders'){$params=$customer?[$a['customer_id']]:[];$rows=crm_query('SELECT o.id,o.number,o.title,f.support_terms,f.support_start,f.support_end FROM nd_orders o JOIN nd_lc_order_flow f ON f.order_id=o.id'.($customer?' WHERE o.customer_id=?':'').' ORDER BY o.id DESC LIMIT 200',$params)->fetchAll();foreach($rows as &$o){$o['access']=sa_state((int)$o['id']);if($customer)unset($o['access']['policy']);}unset($o);json_response(['ok'=>true,'items'=>$rows]);}
  $order=filter_var($_GET['order']??0,FILTER_VALIDATE_INT);$o=$order?crm_record('orders',(int)$order):null;if(!$o||$customer&&(int)$o['customer_id']!==$a['customer_id'])crm_fail(404,'Заказ не найден.');$a['document_archive']=true;
  if($r==='archive'){$items=crm_query("SELECT b.id,t.title,b.state,a.checksum,a.copy_released_at,a.countersigned_file_id FROM nd_lc_document_bindings b JOIN nd_lc_templates t ON t.id=b.template_id JOIN nd_lc_pdf_assets a ON a.binding_id=b.id WHERE b.order_id=? AND b.state IN ('SENT','AGREED') AND a.owner_reviewed_at IS NOT NULL ORDER BY b.id",[$order])->fetchAll();$receipts=crm_query("SELECT e.id,e.official_url,e.file_id FROM nd_lc_receipt_evidence e JOIN nd_lc_receipt_tasks t ON t.id=e.task_id WHERE t.order_id=? AND t.state='TRANSMISSION_RECORDED' AND (e.file_id IS NOT NULL OR e.official_url IS NOT NULL) ORDER BY e.id",[$order])->fetchAll();json_response(['ok'=>true,'receipts'=>$receipts,'items'=>$items,'access'=>array_diff_key(sa_state((int)$order),['policy'=>true]),'automatic_deletion'=>false]);}
  if($r==='receipt'){$e=crm_query("SELECT e.file_id FROM nd_lc_receipt_evidence e JOIN nd_lc_receipt_tasks t ON t.id=e.task_id WHERE e.id=? AND t.order_id=? AND t.state='TRANSMISSION_RECORDED'",[(int)($_GET['receipt']??0),$order])->fetch();if(!$e||!$e['file_id'])crm_fail(404,'Копия официального чека не найдена.');$file=cc_file($a,(int)$e['file_id']);$p=cc_project($a,(int)$file['project_id']);if((int)$p['order_id']!==(int)$order)crm_fail(404,'Копия чека не найдена.');header('Content-Type: '.$file['mime']);header('Content-Disposition: attachment; filename="official-receipt-copy"');header('X-Content-Type-Options: nosniff');readfile(cc_file_path($file));exit;}
  if(in_array($r,['pdf','completed'],true)){$b=lc_binding($a,(int)($_GET['document']??0));if((int)$b['order_id']!==(int)$order||!in_array($b['state'],['SENT','AGREED'],true))crm_fail(404,'Документ не найден.');$asset=ct_asset($b);if(!$asset['owner_reviewed_at'])crm_fail(404,'Документ не найден.');if($r==='pdf')ct_download($b);if(!$asset['copy_released_at']||!$asset['countersigned_file_id']||$b['state']!=='AGREED')crm_fail(404,'Завершённая копия не выпущена.');$file=cc_file($a,(int)$asset['countersigned_file_id']);header('Content-Type: '.$file['mime']);header('Content-Disposition: attachment; filename="completed-copy-'.$b['id'].'"');header('X-Content-Type-Options: nosniff');readfile(cc_file_path($file));exit;}
 }
 if($method==='POST'){$d=input();cc_owner($a);$result=crm_idempotent('support/'.$r,$d,fn()=>match($r){'access-policy'=>sa_save($a,$d),'retention'=>sa_retention($a,$d),default=>throw new CrmFailure(404,'Действие не найдено.')});json_response($result);}crm_fail(404,'Действие не найдено.');
}catch(CrmFailure $e){fail($e->status,$e->getMessage(),'support_error');}catch(CustomerFailure $e){fail($e->status,$e->getMessage(),$e->errorCode);}catch(Throwable $e){server_error($e);}
